INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 44, 'theory', 'Quiz: asyncio');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 44, 0, 'What does calling an async function hello() return, without await and without asyncio.run?', '["The function''s result", "A coroutine object: the body has not run yet", "None", "A syntax error"]', 1, 'A coroutine is prepared work: it has to be awaited with await or started with asyncio.run.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 44, 1, 'What happens on time.sleep(1) inside a coroutine?', '["The coroutine sleeps, the others keep working", "The whole event loop freezes: all coroutines stand still", "Python raises an error", "Nothing special"]', 1, 'A blocking call does not yield control; you need asyncio.sleep or to move the work to a thread.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 44, 2, 'Three tasks of 0.2 s each were created with create_task and awaited. About how long will the wait take?', '["0.6 s", "about 0.2 s", "0.4 s", "0 s"]', 1, 'The waits overlap: the tasks run concurrently.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 44, 3, 'In what order does gather return its results?', '["In order of completion", "In the order the coroutines were passed", "In descending order", "Randomly"]', 1, 'The order of results matches the order of the arguments, no matter which finished first.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 44, 4, 'What should you do with a CancelledError that arrives in a coroutine?', '["Suppress it and continue", "Do not swallow it: let it propagate (clean up in finally)", "Call exit()", "Turn it into a ValueError"]', 1, 'A suppressed cancellation makes the task unstoppable.');
